package dev.theredstonee.trsclient.core.waypoint;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class DioramaFormatTest {
 @Test void nativeFormatRetainsIdsIconsFoldersAndInitialsAcrossTargets(@TempDir Path dir)throws Exception{WaypointStore source=new WaypointStore(dir.resolve("old.json"));source.load();Waypoint p=new Waypoint("Home",10,64,-20,"dim0",0x0090ff);p.initials="HM";p.icon="diorama:home";p.folder="Survival A";source.add("A",p);Path file=dir.resolve("diorama/waypoints.json");source.exportDiorama(file,"A");String json=new String(Files.readAllBytes(file),"UTF-8");assertTrue(json.contains("minecraft:overworld"));WaypointStore loaded=new WaypointStore(dir.resolve("new.json"));loaded.importDiorama(file,"B");Waypoint copy=loaded.all("B").get(0);assertEquals(p.id,copy.id);assertEquals(p.icon,copy.icon);assertEquals(p.folder,copy.folder);assertEquals(p.initials,copy.initials);assertEquals("dim0",copy.dimension);assertEquals(p.color,copy.color);loaded.importDiorama(file,"B");assertEquals(1,loaded.all("B").size());}
 @Test void corruptImportPreservesExistingWaypoints(@TempDir Path dir)throws Exception{WaypointStore store=new WaypointStore(dir.resolve("global.json"));Waypoint p=new Waypoint("Keep",1,64,2,"dim0",0x00ff00);store.add("A",p);Path file=dir.resolve("waypoints.json");Files.write(file,"broken".getBytes("UTF-8"));assertThrows(java.io.IOException.class,()->store.importDiorama(file,"A"));assertSame(p,store.all("A").get(0));}
 @Test void exportingAnotherWorldDoesNotMixDimensionsOrTemporaryPoints(@TempDir Path dir)throws Exception{WaypointStore store=new WaypointStore(dir.resolve("global.json"));Waypoint a=new Waypoint("A",1,64,2,"dim0",1),b=new Waypoint("B",1,64,2,"dim0",2),temp=new Waypoint("Temporary",0,64,0,"dim0",3);temp.temporary=true;store.add("A",a);store.add("B",b);store.add("A",temp);Path file=dir.resolve("waypoints.json");store.exportDiorama(file,"A");WaypointStore imported=new WaypointStore(dir.resolve("new.json"));imported.importDiorama(file,"A");assertEquals(1,imported.all("A").size());assertEquals("A",imported.all("A").get(0).name);}
}
